#!/bin/sh
# GENERATED by bake.py from /etc/event.d/ce-reclaim-customization-media -- do not edit.
# Lives outside the job because upstart segfaults spawning a job
# with a large inline script (see externalise_job_scripts).
# Run by that job as `sh -e`: a lone failing command aborts it.
    FLAG=/var/luna/preferences/ce-customization-media-reclaimed
    LOG=/var/log/ce-reclaim-customization-media.log
    log() { echo "$(date 2>/dev/null) $*" >> "$LOG" 2>/dev/null; }
    STAGE=/usr/lib/luna/customization/copy_binaries/media/internal
    DONE=/var/luna/data/Customization/system_complete.txt
    if [ -f "$FLAG" ]; then exit 0; fi
    if [ ! -d "$STAGE" ]; then
        log "nothing staged -- already reclaimed, or this image ships no media"
        mkdir -p /var/luna/preferences && touch "$FLAG"
        exit 0
    fi
    # The customization service is what copies these; it must have finished.
    if [ ! -f "$DONE" ]; then
        log "customization service not finished -- deferring to the next trigger"
        exit 0
    fi
    # VERIFY the payload actually landed before deleting the only other copy.
    # A short count means the copy did not complete and the staging copy is
    # still the only good source.
    bad=0
    for d in wallpapers ringtones music; do
        [ -d "$STAGE/$d" ] || continue
        st=$(ls -1 "$STAGE/$d" 2>/dev/null | wc -l)
        lv=$(ls -1 "/media/internal/$d" 2>/dev/null | wc -l)
        if [ "$lv" -lt "$st" ]; then
            log "VERIFY FAILED $d: staged=$st live=$lv -- keeping the staging copy"
            bad=$((bad+1))
        else
            log "verified $d: staged=$st live=$lv"
        fi
    done
    if [ $bad -ne 0 ]; then
        log "$bad directory(ies) unverified -- NOT flagging, will retry"
        exit 0
    fi
    # ce-firstboot-tweaks and ce-remove-preloads also flip / rw->ro; take the
    # shared lock so neither remounts under the other.
    L=/tmp/.ce-rootfs-rw.lock
    n=0
    while ! mkdir $L 2>/dev/null && [ $n -lt 60 ]; do sleep 1; n=$((n+1)); done
    # busybox df WRAPS a long device name onto a second line, so NR==2 is the
    # continuation and $4 is empty. Take the last line and count from the end.
    before=$(df -k / 2>/dev/null | awk "END{print \$(NF-2)}")
    mount -o remount,rw / 2>/dev/null || true
    rm -rf "$STAGE"
    sync
    mount -o remount,ro / 2>/dev/null || true
    rmdir $L 2>/dev/null || true
    if [ -d "$STAGE" ]; then
        log "FAILED to remove $STAGE -- NOT flagging, will retry"
        exit 0
    fi
    after=$(df -k / 2>/dev/null | awk "END{print \$(NF-2)}")
    log "reclaimed staged media: / free ${before}K -> ${after}K"
    mkdir -p /var/luna/preferences && touch "$FLAG"
